#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# Run from the project root so .env and research/ resolve there.
cd "$(dirname "$0")/.."

FINDINGS_FILE="research/manual-findings.md"
NOTED=() # findings appended to FINDINGS_FILE this run

# log_finding "Title" "body" appends a dated section to FINDINGS_FILE.
log_finding() {
  [[ -f "$FINDINGS_FILE" ]] || printf '# Manual findings (written by scripts/data-access-wizard.sh)\n' > "$FINDINGS_FILE"
  printf '\n## %s (%s)\n\n%s\n' "$1" "$(date +%Y-%m-%d)" "$2" >> "$FINDINGS_FILE"
  NOTED+=("$1")
  printf '  %s✓ noted%s %s → %s\n' "$GREEN" "$RESET" "$1" "$FINDINGS_FILE"
}

# http_status URL [curl args...] prints the HTTP status code, or 000 on failure.
http_status() {
  local url="$1"; shift
  if ! command -v curl >/dev/null 2>&1; then echo "000"; return; fi
  curl -s -o /dev/null -w '%{http_code}' --max-time 30 "$@" "$url" || echo "000"
}

# lai_stage "Title" FILE explains and records one e-SIC request.
lai_stage() {
  local title="$1" file="$2" due
  stage "LAI request: $title"
  say "File this request on the Prefeitura's e-SIC. Copy the text below:"
  printf '\n'
  sed 's/^/    /' "$file"
  printf '\n'
  note "(Same text in $file.)"
  open_url "https://cascavel.atende.net/cidadao/acesso-informacao"
  step "Click 'Nova Solicitação'. The form opens in a new tab."
  step "Sign in or register in the Portal do Cidadão if it asks (LAI requests need identification)."
  step "Paste the text above into the request field, then submit."
  note "I couldn't check the form's fields, so follow its own labels."
  if confirm "Did you submit it?"; then
    ask LAI_PROTOCOL "Paste the protocol number it gave you:"
    due=$(date -d '+20 days' +%d/%m/%Y 2>/dev/null || date -v+20d +%d/%m/%Y)
    log_finding "LAI: $title" "- Protocol: ${LAI_PROTOCOL}
- Filed: $(date +%d/%m/%Y). Answer due by ${due} (20 days, extendable by 10; LAI art. 11).
- Text: $file
- Track at https://cascavel.atende.net/cidadao/acesso-informacao → Acompanhar Solicitação."
  else
    SKIPPED+=("LAI request: $title ($file)")
  fi
}

banner "Cascavel transparency portal: data access"

# ── 1. CGU API key ────────────────────────────────────────────────────────
stage "CGU Portal da Transparência API key"
say "Needed for federal transfers, convênios and Bolsa Família by municipality."
open_url "https://portaldatransparencia.gov.br/api-de-dados/cadastrar-email"
step "Click 'Entrar com gov.br'."
step "Use a Prata or Ouro gov.br account, or CPF + password with two-step verification turned on."
step "The token arrives at the email on your gov.br account. Copy it from that email."
ask_secret CGU_API_KEY "Paste the CGU token:"
if [[ -n "$CGU_API_KEY" ]]; then
  write_env CGU_API_KEY "$CGU_API_KEY"
  code=$(http_status "https://api.portaldatransparencia.gov.br/api-de-dados/bolsa-familia-por-municipio?mesAno=202601&codigoIbge=4104808&pagina=1" -H "chave-api-dados: $CGU_API_KEY")
  case "$code" in
    200) printf '  %s✓ test call worked%s (Bolsa Família, Cascavel, 01/2026)\n' "$GREEN" "$RESET" ;;
    401|403) warn "test call returned $code: the token was rejected. Check you pasted all of it." ;;
    *) warn "test call returned $code. The key is saved; try the API again later." ;;
  esac
else
  SKIPPED+=("CGU API key (https://portaldatransparencia.gov.br/api-de-dados/cadastrar-email)")
fi
pause

# ── 2. dados.gov.br API key (optional) ────────────────────────────────────
stage "dados.gov.br API key (optional)"
say "Only the federal open-data catalog needs this. Skip it if you don't plan to search the catalog."
if confirm "Get a dados.gov.br key now?"; then
  open_url "https://dados.gov.br/"
  step "Click 'Entrar com gov.br' and sign in."
  step "Open 'Minha Conta' and copy your API key."
  note "I couldn't check the exact labels on that page."
  ask_secret DADOS_GOV_API_KEY "Paste the dados.gov.br key:"
  if [[ -n "$DADOS_GOV_API_KEY" ]]; then
    write_env DADOS_GOV_API_KEY "$DADOS_GOV_API_KEY"
    code=$(http_status "https://dados.gov.br/dados/api/publico/conjuntos-dados?pagina=1" -H "chave-api-dados-abertos: $DADOS_GOV_API_KEY")
    if [[ "$code" == "200" ]]; then
      printf '  %s✓ test call worked%s\n' "$GREEN" "$RESET"
    else
      warn "test call returned $code. The key is saved; check it on the site."
    fi
  else
    SKIPPED+=("dados.gov.br API key")
  fi
else
  note "Skipped."
fi
pause

# ── 3-5. LAI requests ─────────────────────────────────────────────────────
lai_stage "spending by empenho" "research/lai-requests/01-empenhos.txt"
pause
lai_stage "monthly payroll" "research/lai-requests/02-folha.txt"
pause
lai_stage "health and education data" "research/lai-requests/03-saude-educacao.txt"
pause

# ── 6. Inventário de Dados Abertos ────────────────────────────────────────
stage "Check: the Prefeitura's open data inventory"
say "The research agent couldn't see this page: it's behind a Cloudflare human check."
open_url "https://prefa.cascavel.pr.gov.br/transparencia/item/inventario-de-dados-abertos"
step "If 'Verify you are human' appears, complete it."
step "Look at the list of datasets: which ones exist, their formats, and how often they update."
ask INVENTARIO_NOTES "Summarize what's listed (one line is fine):"
log_finding "Inventário de Dados Abertos" "- URL: https://prefa.cascavel.pr.gov.br/transparencia/item/inventario-de-dados-abertos
- Contents: ${INVENTARIO_NOTES}"
pause

# ── 7. Grid export formats ────────────────────────────────────────────────
stage "Check: what the spending grid exports"
say "If the grid's export has item-by-item empenhos, it can fill the gap the API leaves."
open_url "https://prefa.cascavel.pr.gov.br/transparencia/mapa-do-site"
step "Under Despesas, open the empenhos item. Complete the human check if asked."
step "Pick a short period (one week) and click 'Consultar'."
step "Click 'Dados Abertos' (or 'Imprimir/Exportar') and note the formats offered."
step "Download one file. Does it have the empenho number, date and object?"
ask GRID_EXPORT_NOTES "Formats offered, and what the file contains:"
ask GRID_EXPORT_URL "If the download had a link you can copy, paste it (Enter to skip):"
body="- Notes: ${GRID_EXPORT_NOTES}"
if [[ -n "$GRID_EXPORT_URL" ]]; then
  code=$(http_status "$GRID_EXPORT_URL")
  body="${body}
- Export link: ${GRID_EXPORT_URL}
- Fetching it without a browser returned HTTP ${code}."
fi
log_finding "IPM grid export (empenhos)" "$body"
pause

# ── 8. Diário Oficial PDF link pattern ────────────────────────────────────
stage "Check: Diário Oficial PDF links"
say "We need a real PDF link to know whether editions can be downloaded by a script."
open_url "https://prefa.cascavel.pr.gov.br/diariooficial/edicao"
step "Find the latest edition and right-click its download button."
step "Choose 'Copy link address'."
ask DIARIO_OFICIAL_PDF_URL_EXAMPLE "Paste the PDF link:"
if [[ -n "$DIARIO_OFICIAL_PDF_URL_EXAMPLE" ]]; then
  write_env DIARIO_OFICIAL_PDF_URL_EXAMPLE "$DIARIO_OFICIAL_PDF_URL_EXAMPLE"
  code=$(http_status "$DIARIO_OFICIAL_PDF_URL_EXAMPLE")
  if [[ "$code" == "200" ]]; then
    printf '  %s✓ the link downloads without a browser%s\n' "$GREEN" "$RESET"
  else
    warn "fetching it without a browser returned HTTP $code"
  fi
  log_finding "Diário Oficial PDF link" "- Example: ${DIARIO_OFICIAL_PDF_URL_EXAMPLE}
- Fetching it without a browser returned HTTP ${code}."
else
  SKIPPED+=("Diário Oficial PDF link (https://prefa.cascavel.pr.gov.br/diariooficial/edicao)")
fi
pause

# ── 9. Paraná state downloads ─────────────────────────────────────────────
stage "Check: Paraná state transparency downloads"
say "The download links on this page only appear in a browser."
open_url "https://www.transparencia.pr.gov.br/pte/assunto/8/129"
step "Look at Gastos Públicos, Licitações, Contratos and Convênios."
step "Note each one's file format, and whether the files name the municipality receiving the money."
ask PR_DOWNLOADS_NOTES "Formats, and whether Cascavel can be filtered:"
step "Right-click the most recent Gastos Públicos file and copy its link."
ask PR_GASTOS_URL "Paste that link (Enter to skip):"
body="- Notes: ${PR_DOWNLOADS_NOTES}"
if [[ -n "$PR_GASTOS_URL" ]]; then
  code=$(http_status "$PR_GASTOS_URL")
  body="${body}
- Gastos Públicos link: ${PR_GASTOS_URL}
- Fetching it without a browser returned HTTP ${code}."
fi
log_finding "Paraná state Downloads page" "$body"
pause

finish
(( ${#NOTED[@]} )) && note "added ${#NOTED[@]} finding(s) to $FINDINGS_FILE"
printf '\n'
